changeSet.sql:
CREATE TABLE library_files ( file_id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), book_id UUID REFERENCES lib_books(id) ON DELETE CASCADE, bucket TEXT NOT NULL, storage_key TEXT NOT NULL, source_url TEXT, source_type TEXT NOT NULL CHECK (source_type IN ('SHAMELA','ARCHIVE_ORG','USER_UPLOAD','SCAN','DERIVED')), content_hash TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0), etag TEXT, downloaded_at TIMESTAMPTZ NOT NULL, last_verified_at TIMESTAMPTZ, shamela_major_release INTEGER, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, deleted_at TIMESTAMPTZ, UNIQUE (bucket, storage_key) );
CREATE INDEX idx_library_files_book_id ON library_files(book_id) WHERE book_id IS NOT NULL;
CREATE INDEX idx_library_files_source_url ON library_files(source_url) WHERE source_url IS NOT NULL;
CREATE INDEX idx_library_files_active ON library_files(bucket, storage_key) WHERE deleted_at IS NULL;
CREATE INDEX idx_library_files_source_type ON library_files(source_type);
